export const getLegalPolicyById = (id: string): LegalPolicy | undefined => {
  return ROUTRIPO_LEGAL_POLICIES.find(p => p.id === id || p.slug === id);
};

export const getLegalPolicyBySlug = (slug: string): LegalPolicy | undefined => {
  return ROUTRIPO_LEGAL_POLICIES.find(p => p.slug === slug || p.id === slug);
};
